chapter(7, 'My shifts and pay, and appearance', 'See your own shift, week, leave and payslip on the phone, and make the text larger on this device.', 'Ravi (Housekeeper)', 'housekeeper', menu='People & Payroll > My shifts & pay', display='mobile')
step('Ravi opens People & Payroll. For him the module has one page, My shifts & pay.', 'Every employee sees their own shifts and pay.', target='sel:main', auto=['click:menutop:People & Payroll'], action='click', expect='My shifts & pay opens.', check="ctx.page==='my-hr'")
read('The page shows today\'s shift, Morning 07:00 to 15:00, your week, the month so far, the latest payslip and your leave. Nobody else\'s pay is shown.', 'You always know where you stand.', target='sel:main', expect='The shift and pay page.')
click('btn:September 2026', 'Tap the payslip of September 2026.', 'The payslip shows the earnings, the deductions and the net pay.', expect='The payslip opens.')
click('btn:Request leave', 'Tap Request leave.', 'Leave is asked for on the phone and approved by a manager.', expect='The Add Leave sheet opens.', check="has('Add Leave')")
step('Choose the approver Meera, the date 31 Oct and the reason Family function.', 'The quota is checked again at approval.', target='field:Reason', auto=['select:field:Approver|Meera', 'type:field:Leave From|2026-10-31', 'type:field:Leave To|2026-10-31', 'type:field:Reason|Family function'], action='type', expect='The leave request is filled.')
click('modalbtn:Add Leave', 'Tap Add Leave.', 'The request goes to the manager.', expect='The leave request is saved.', allowError=True)
step('Open Admin & Setup, Appearance & display. Text size, theme and start page belong to this device only.', 'A larger text helps in the sun and with tired eyes.', target='sel:main', auto=['key:Escape', 'click:btn:Menu', 'click:btn:Admin & Setup', 'click:menuleaf:Appearance & display'], action='click', expect='Appearance & display opens.', check="ctx.page==='prefs'")
click('btn:Large', 'Tap Large for the text size.', 'The whole app grows at once; printed documents are never affected.', expect='The text is larger.')
